import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as o,o as r,j as i,G as a,ae as n,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Immediate Expansion of American Timber Production","description":"","frontmatter":{"legisId":"2025-03-01-immediate-expansion-of-american-timber-production","title":"Immediate Expansion of American Timber Production","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/immediate-expansion-of-american-timber-production/","publishDate":"2025-03-01","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Immediate Expansion of American Timber Production\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-03-01-immediate-expansion-of-american-timber-production\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Immediate Expansion of American Timber Production\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-03-01-immediate-expansion-of-american-timber-production\\",\\"datePublished\\":\\"2025-03-01\\",\\"dateModified\\":1768094639000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-03-01-immediate-expansion-of-american-timber-production\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-03-01-immediate-expansion-of-american-timber-production.md","filePath":"executive-orders/2025-03-01-immediate-expansion-of-american-timber-production.md","lastUpdated":1768094639000}'),l={name:"executive-orders/2025-03-01-immediate-expansion-of-american-timber-production.md"},h=Object.assign(l,{setup(c){return(m,e)=>(r(),o("div",null,[e[0]||(e[0]=i("h1",{id:"immediate-expansion-of-american-timber-production",tabindex:"-1"},[s("Immediate Expansion of American Timber Production "),i("a",{class:"header-anchor",href:"#immediate-expansion-of-american-timber-production","aria-label":'Permalink to "Immediate Expansion of American Timber Production"'},"​")],-1)),a(t),e[1]||(e[1]=n('<p>Published on Saturday, March 1, 2025</p><h1 id="summary-of-timber-production-executive-order" tabindex="-1">Summary of Timber Production Executive Order <a class="header-anchor" href="#summary-of-timber-production-executive-order" aria-label="Permalink to &quot;Summary of Timber Production Executive Order&quot;">​</a></h1><h2 id="section-1-purpose" tabindex="-1">Section 1: Purpose <a class="header-anchor" href="#section-1-purpose" aria-label="Permalink to &quot;Section 1: Purpose&quot;">​</a></h2><ul><li>Timber production is essential for: <ul><li>Construction</li><li>Energy production</li><li>Forest management and wildfire risk reduction, which can save lives</li></ul></li><li>The U.S. has sufficient timber resources, but: <ul><li>Federal policies hinder full utilization</li><li>Reliance on foreign lumber poses economic risks and job losses</li></ul></li><li>Aims to reverse these policies to enhance domestic timber production and secure economic stability.</li></ul><h2 id="section-2-directives-to-the-secretaries" tabindex="-1">Section 2: Directives to the Secretaries <a class="header-anchor" href="#section-2-directives-to-the-secretaries" aria-label="Permalink to &quot;Section 2: Directives to the Secretaries&quot;">​</a></h2><ul><li><p><strong>Within 30 days:</strong></p><ul><li>Issue updated guidance for increased timber production and forest management.</li><li>Submit legislative proposals to improve timber production capabilities.</li></ul></li><li><p><strong>Within 60 days:</strong></p><ul><li>Develop a strategy under the Endangered Species Act (ESA) to expedite forestry project approvals.</li></ul></li><li><p><strong>Within 90 days:</strong></p><ul><li>Submit a plan setting targets for annual timber sales from federal lands for the next 4 years.</li></ul></li><li><p><strong>Within 120 days:</strong></p><ul><li>Complete the Whitebark Pine Rangewide Programmatic Consultation under the ESA.</li></ul></li><li><p><strong>Within 180 days:</strong></p><ul><li>Consider adopting categorical exclusions to streamline processes for timber production and related activities.</li></ul></li><li><p><strong>Within 280 days:</strong></p><ul><li>Consider establishing a new categorical exclusion for timber thinning and restore for salvage activities.</li></ul></li></ul><h2 id="section-3-streamlined-permitting" tabindex="-1">Section 3: Streamlined Permitting <a class="header-anchor" href="#section-3-streamlined-permitting" aria-label="Permalink to &quot;Section 3: Streamlined Permitting&quot;">​</a></h2><ul><li>Agencies must eliminate undue delays in permitting for timber production.</li><li>Revise or rescind regulations that impose burdens on timber production.</li></ul><h2 id="section-4-endangered-species-committee-esc" tabindex="-1">Section 4: Endangered Species Committee (ESC) <a class="header-anchor" href="#section-4-endangered-species-committee-esc" aria-label="Permalink to &quot;Section 4: Endangered Species Committee (ESC)&quot;">​</a></h2><ul><li>Utilize ESA regulations for consultations in emergencies to boost timber production.</li><li>ESC is to review submissions efficiently and resolve exemption application issues promptly.</li><li>Federal members should report on obstacles to timber production due to ESA and recommend improvements.</li></ul><h2 id="section-5-general-provisions" tabindex="-1">Section 5: General Provisions <a class="header-anchor" href="#section-5-general-provisions" aria-label="Permalink to &quot;Section 5: General Provisions&quot;">​</a></h2><ul><li>The order does not affect the authority of executive departments or agencies.</li><li>It will be implemented per applicable laws and existing appropriations.</li><li>The order does not create enforceable rights against the U.S. or its entities.</li></ul><p><strong>Date of Order:</strong> March 1, 2025</p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/immediate-expansion-of-american-timber-production/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/immediate-expansion-of-american-timber-production/</a></p>',14))]))}});export{u as __pageData,h as default};
